require_once __DIR__.'/core.php';require_once __DIR__.'/tag_engine.php';require_once __DIR__.'/federation_lib.php';require_once __DIR__.'/maintenance.php';$logged=!empty($_SESSION['loggedin']);$user=(string)($_SESSION['name']??'');$q=trim((string)($_GET['q']??''));$scope=trim((string)($_GET['scope']??'all'));$type=trim((string)($_GET['type']??'all'));$db=tt_db_open(true);try{tt_opportunistic_maintenance($db);tt_federation_tick($db);}catch(Throwable $e){}
$where=[];$params=[];$types='';if($logged){[$v,$vp,$vt]=tt_visible_where('p');$where[]=$v;$params=array_merge($params,$vp);$types.=$vt;}else{$where[]="p.`scope` IN ('global','public','public ')";}if($q!==''){$where[]='(p.`title` LIKE ? OR p.`content` LIKE ? OR p.`tags` LIKE ? OR p.`name` LIKE ? OR EXISTS (SELECT 1 FROM `tag_index` ti WHERE ti.`post_id`=p.`id` AND (ti.`tag` LIKE ? OR ti.`raw_token` LIKE ?)))';$like='%'.$q.'%';for($i=0;$i<6;$i++)$params[]=$like;$types.='ssssss';}if($scope!=='all'&&in_array($scope,['global','public','private'],true)){if($scope==='private'&&!$logged)$scope='all';else{$where[]='TRIM(p.`scope`)=?';$params[]=$scope;$types.='s';}}if($type!=='all'&&in_array($type,['post','media','message','event','group','forum'],true)){$where[]='p.`type`=?';$params[]=$type;$types.='s';}$sql='SELECT p.`id`,p.`title`,p.`content`,p.`dt`,p.`file`,p.`tags`,p.`name`,p.`comments`,p.`scope`,p.`recipients`,p.`type`,p.`votes`,p.`federated`,p.`origin_host` FROM `posts` p WHERE '.implode(' AND ',$where).' ORDER BY p.`dt` DESC,p.`id` DESC LIMIT 250';$s=tt_prepare($db,$sql);if($types!=='')$s->bind_param($types,...$params);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();$db->close();if($q!==''){foreach($rows as &$r)$r['_score']=tt_tag_relevance($q,(string)$r['tags']);unset($r);usort($rows,fn($a,$b)=>(($b['_score']<=>$a['_score'])?:strcmp((string)$b['dt'],(string)$a['dt'])));} $rows=array_slice($rows,0,100);
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Posts</title></head><body><?php if($logged): tt_nav('post.php'); else: ?><nav class="navtop"><div><h1><a href="/">TABLETIME</a></h1><a href="post.php">Posts</a><a href="tags.php">Tags</a><a href="extend.php">Extend</a><a href="login.php">Login</a><a href="register.php">Register</a></div></nav><?php endif;?><main class="content"><?php if(isset($_GET['posted'])):?><p class="notice ok">Post #<?=(int)$_GET['posted']?> published and indexed.</p><?php endif;?><?php if(isset($_GET['deleted'])):?><p class="notice ok">Post deleted.</p><?php endif;?><form method="get" class="searchbar"><input name="q" value="<?=tt_h($q)?>" placeholder="Search text or tags"><select name="scope"><option value="all">all scopes</option><option value="public" <?=$scope==='public'?'selected':''?>>public</option><option value="global" <?=$scope==='global'?'selected':''?>>global</option><?php if($logged):?><option value="private" <?=$scope==='private'?'selected':''?>>private</option><?php endif;?></select><select name="type"><option value="all">all types</option><?php foreach(['post','media','message','event','group','forum'] as $t):?><option value="<?=$t?>" <?=$type===$t?'selected':''?>><?=$t?></option><?php endforeach;?></select><button>Search</button></form><p class="meta"><?=count($rows)?> matching posts.</p><section class="grid"><?php foreach($rows as $r):?><article class="card" id="post-<?=(int)$r['id']?>"><h2><?=tt_h($r['title'])?></h2><p class="meta">#<?=(int)$r['id']?> · <?=tt_h($r['name'])?> · <?=tt_h($r['dt'])?> · <?=tt_h(trim($r['scope']))?> · <?=tt_h($r['type'])?><?=$r['federated']?' · federated':''?><?php if(isset($r['_score'])):?> · tag score <?=number_format((float)$r['_score'],3)?><?php endif;?></p><p><?=nl2br(tt_h($r['content']))?></p><?php if($r['file']!==''):?><p><a href="<?=tt_h($r['file'])?>" rel="noopener">Attachment</a></p><?php endif;?><div><?php foreach(tt_parse_tags((string)$r['tags']) as $tag):?><a class="tag" href="?q=<?=rawurlencode($tag['raw'])?>"><?=tt_h($tag['raw'])?></a><?php endforeach;?></div><?php if(trim((string)$r['comments'])!==''):?><details><summary>Comments</summary><pre><?=tt_h($r['comments'])?></pre></details><?php endif;?><?php if($logged):?><div class="actions"><a href="create.php">Comment / reply</a><?php if(hash_equals($user,(string)$r['name'])):?><form method="post" action="delete.php" style="display:inline;padding:0;margin:0;background:none;border:0"><input type="hidden" name="post_id" value="<?=(int)$r['id']?>"><button type="submit" onclick="return confirm('Delete this post?')">Delete</button></form><?php endif;?></div><?php endif;?></article><?php endforeach;?><?php if(!$rows):?><article class="card"><h2>No posts matched</h2><p>Try a broader search or publish a post.</p></article><?php endif;?></section></main></body></html>
